#include <bits/stdc++.h>
using namespace std;
struct Node {
    long long val;
    Node* left = nullptr;
    Node* right = nullptr;
    Node(long long v) : val(v) {}
};
Node* build(const vector<string>& t) {
    Node* root = new Node(stoll(t[0]));
    queue<Node*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < t.size()) {
        Node* node = q.front(); q.pop();
        if (i < t.size() && t[i] != "null") { node->left = new Node(stoll(t[i])); q.push(node->left); }
        i++;
        if (i < t.size() && t[i] != "null") { node->right = new Node(stoll(t[i])); q.push(node->right); }
        i++;
    }
    return root;
}
Node* readTree() {
    int n;
    cin >> n;
    vector<string> t(n);
    for (auto& s : t) cin >> s;
    return build(t);
}
vector<long long> pre, ino, post;
void walk(Node* node) {
    if (!node) return;
    pre.push_back(node->val);
    walk(node->left);
    ino.push_back(node->val);
    walk(node->right);
    post.push_back(node->val);
}
void print(const vector<long long>& v) {
    for (size_t i = 0; i < v.size(); i++) cout << v[i] << (i + 1 < v.size() ? " " : "\n");
}
int main() {
    walk(readTree());
    print(pre); print(ino); print(post);
    return 0;
}

